// Demonstrating true thread parallelism in Node.js with worker_threads
// Each worker runs in a separate OS thread with its own V8 isolate.

const { Worker, isMainThread, parentPort, workerData } = require('worker_threads');

if (isMainThread) {
  // ── Main thread: spawn two workers for CPU-bound tasks ──────
  function runWorker(taskName, iterations) {
    return new Promise((resolve, reject) => {
      const worker = new Worker(__filename, {
        workerData: { taskName, iterations }
      });
      worker.on('message', resolve);
      worker.on('error', reject);
    });
  }

  const start = Date.now();

  // Both workers start simultaneously — true parallelism on separate cores
  Promise.all([
    runWorker('A', 100_000_000),
    runWorker('B', 100_000_000)
  ]).then(([resultA, resultB]) => {
    const elapsed = Date.now() - start;
    console.log(resultA);            // Task A: sum=4999999950000000 in ~320ms
    console.log(resultB);            // Task B: sum=4999999950000000 in ~320ms
    console.log(`Total: ${elapsed}ms`); // ~320ms — same as ONE task, not 640ms
    // If these ran sequentially on one thread, total would be ~640ms
  });

} else {
  // ── Worker thread: runs in a separate OS thread ──────────────
  const { taskName, iterations } = workerData;
  const start = Date.now();
  let sum = 0;
  for (let i = 0; i < iterations; i++) sum += i;
  const elapsed = Date.now() - start;
  parentPort.postMessage(`Task ${taskName}: sum=${sum} in ${elapsed}ms`);
}

// SharedArrayBuffer — shared memory between Node.js worker threads
// This is the thread-level equivalent of IPC shared memory.

const { Worker, isMainThread, parentPort, workerData } = require('worker_threads');

if (isMainThread) {
  // Allocate a shared buffer — accessible from ALL threads simultaneously
  const sharedBuffer = new SharedArrayBuffer(4); // 4 bytes = one Int32
  const counter = new Int32Array(sharedBuffer);
  counter[0] = 0;

  console.log('Before:', counter[0]); // 0

  // Launch two workers that both increment the counter
  const w1 = new Worker(__filename, { workerData: { sharedBuffer, id: 1 } });
  const w2 = new Worker(__filename, { workerData: { sharedBuffer, id: 2 } });

  let done = 0;
  const onDone = () => {
    done++;
    if (done === 2) {
      // Expected: 200000, but without atomics you may get less due to race condition
      console.log('After:', counter[0]);
    }
  };
  w1.on('message', onDone);
  w2.on('message', onDone);

} else {
  const counter = new Int32Array(workerData.sharedBuffer);
  const ITERATIONS = 100_000;

  // RACE CONDITION VERSION (comment this in to see the bug):
  // for (let i = 0; i < ITERATIONS; i++) counter[0]++;  // Not atomic!

  // CORRECT VERSION — Atomics.add is guaranteed to be indivisible:
  for (let i = 0; i < ITERATIONS; i++) {
    Atomics.add(counter, 0, 1); // atomic increment — no race condition
  }
  parentPort.postMessage('done');
}

// Visualising the event loop's execution order
// Run this and predict the output before reading the explanation.

console.log('1 — synchronous, runs immediately');

setTimeout(() => {
  console.log('4 — macrotask: setTimeout callback (task queue)');
}, 0); // Even with 0ms delay, waits for current call stack to clear

Promise.resolve().then(() => {
  console.log('3 — microtask: Promise.then (microtask queue)');
  // Microtasks run before the next macrotask
  return Promise.resolve();
}).then(() => {
  console.log('3b — microtask: chained .then');
});

queueMicrotask(() => {
  console.log('3c — microtask: queueMicrotask');
});

console.log('2 — synchronous, runs before any async callbacks');

// Predicted output order:
// 1 — synchronous, runs immediately
// 2 — synchronous, runs before any async callbacks
// 3 — microtask: Promise.then (microtask queue)
// 3b — microtask: chained .then
// 3c — microtask: queueMicrotask
// 4 — macrotask: setTimeout callback (task queue)

// KEY INSIGHT: ALL microtasks drain before ANY macrotask runs.
// If a microtask schedules another microtask, it also runs before macrotasks.
// This is why infinite Promise chains can starve setTimeout callbacks.
